function healthCheckLoop(servers, interval, timeout, threshold):
    for server in servers:
        server.consecutiveFailures = 0
        server.status = HEALTHY

    loop forever:
        for server in servers:
            result = sendProbe(server.healthEndpoint, timeout)

            if result == SUCCESS:
                server.consecutiveFailures = 0
                if server.status != HEALTHY:
                    server.status = HEALTHY
                    addToPool(server)
                    log("server recovered:", server.id)
            else:
                server.consecutiveFailures += 1
                if server.consecutiveFailures >= threshold and server.status == HEALTHY:
                    server.status = UNHEALTHY
                    removeFromPool(server)
                    log("server marked unhealthy:", server.id)

        sleep(interval)

