def health_check_loop(servers, interval=2.0, timeout=0.5, threshold=3):
    for s in servers:
        s.consecutive_failures = 0
        s.status = "HEALTHY"

    while True:
        for s in servers:
            ok = send_probe(s.health_endpoint, timeout=timeout)

            if ok:
                s.consecutive_failures = 0
                if s.status != "HEALTHY":
                    s.status = "HEALTHY"
                    add_to_pool(s)
                    log("server recovered:", s.id)
            else:
                s.consecutive_failures += 1
                if s.consecutive_failures >= threshold and s.status == "HEALTHY":
                    s.status = "UNHEALTHY"
                    remove_from_pool(s)
                    log("server marked unhealthy:", s.id)

        time.sleep(interval)
